class VoiceCommandSystem {
  constructor() {
    this.commands = new Map();
    this.isListening = false;
    this.setupRecognition();
  }

  setupRecognition() {
    if (!('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) {
      console.error('Speech recognition not supported');
      return;
    }

    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    this.recognition = new SpeechRecognition();

    this.recognition.continuous = true;
    this.recognition.interimResults = false;
    this.recognition.lang = 'en-US';

    this.recognition.onresult = (event) => {
      const command = event.results[event.results.length - 1][0].transcript.toLowerCase().trim();
      this.processCommand(command);
    };

    this.recognition.onerror = (event) => {
      console.error('Recognition error:', event.error);
    };
  }

  addCommand(phrase, callback) {
    this.commands.set(phrase.toLowerCase(), callback);
  }

  processCommand(command) {
    console.log('Heard command:', command);

    // Check for exact matches first
    if (this.commands.has(command)) {
      this.commands.get(command)();
      return;
    }

    // Check for partial matches
    for (const [phrase, callback] of this.commands) {
      if (command.includes(phrase)) {
        callback();
        return;
      }
    }

    console.log('Unknown command:', command);
  }

  startListening() {
    if (this.recognition && !this.isListening) {
      this.recognition.start();
      this.isListening = true;
    }
  }

  stopListening() {
    if (this.recognition && this.isListening) {
      this.recognition.stop();
      this.isListening = false;
    }
  }
}

// Usage example
const voiceCommands = new VoiceCommandSystem();

// Add commands
voiceCommands.addCommand('hello', () => {
  speak('Hello! How can I help you?');
});

voiceCommands.addCommand('time', () => {
  const now = new Date().toLocaleTimeString();
  speak(`The current time is ${now}`);
});

voiceCommands.addCommand('scroll down', () => {
  window.scrollBy(0, 300);
});

// Start listening
voiceCommands.startListening();

