// Fetch with timeout
function fetchWithTimeout(url, options = {}, timeout = 5000) {
  return Promise.race([
    fetch(url, options),
    new Promise((_, reject) => 
      setTimeout(() => reject(new Error('Request timeout')), timeout)
    )
  ]);
}

// Retry mechanism
async function fetchWithRetry(url, options = {}, maxRetries = 3) {
  for (let i = 0; i <= maxRetries; i++) {
    try {
      const response = await fetch(url, options);
      if (response.ok) {
        return response;
      }
      throw new Error(`HTTP ${response.status}`);
    } catch (error) {
      if (i === maxRetries) {
        throw error;
      }
      console.log(`Retry ${i + 1}/${maxRetries} after error:`, error.message);
      await new Promise(resolve => setTimeout(resolve, 1000 * (i + 1)));
    }
  }
}

// Request interceptor utility
class FetchInterceptor {
  constructor(baseURL = '') {
    this.baseURL = baseURL;
    this.requestInterceptors = [];
    this.responseInterceptors = [];
  }

  addRequestInterceptor(interceptor) {
    this.requestInterceptors.push(interceptor);
  }

  addResponseInterceptor(interceptor) {
    this.responseInterceptors.push(interceptor);
  }

  async fetch(url, options = {}) {
    let finalUrl = url.startsWith('http') ? url : this.baseURL + url;
    let finalOptions = { ...options };

    // Apply request interceptors
    for (const interceptor of this.requestInterceptors) {
      const result = interceptor(finalUrl, finalOptions);
      if (result) {
        finalUrl = result.url || finalUrl;
        finalOptions = result.options || finalOptions;
      }
    }

    let response = await fetch(finalUrl, finalOptions);

    // Apply response interceptors
    for (const interceptor of this.responseInterceptors) {
      response = interceptor(response) || response;
    }

    return response;
  }
}

// Usage example
const api = new FetchInterceptor('https://api.example.com');

// Add auth header to all requests
api.addRequestInterceptor((url, options) => {
  options.headers = options.headers || {};
  options.headers.Authorization = 'Bearer ' + getAuthToken();
  return { url, options };
});

// Log all responses
api.addResponseInterceptor((response) => {
  console.log('Response:', response.status, response.url);
  return response;
});

