let watchId = null;

function startLocationTracking() {
  if ('geolocation' in navigator) {
    const options = {
      enableHighAccuracy: true,
      timeout: 5000,
      maximumAge: 0 // Always get fresh position
    };

    watchId = navigator.geolocation.watchPosition(
      // Success callback - called whenever position changes
      function(position) {
        const coords = position.coords;
        const timestamp = new Date(position.timestamp);

        console.log('Position update:', {
          latitude: coords.latitude,
          longitude: coords.longitude,
          accuracy: coords.accuracy,
          timestamp: timestamp.toLocaleString()
        });

        // Update UI with new position
        updateLocationDisplay(coords);

        // Log movement if significant change
        if (hasSignificantMovement(coords)) {
          logMovement(coords, timestamp);
        }
      },

      // Error callback
      function(error) {
        console.error('Watch position error:', error.message);

        // Optionally stop watching on persistent errors
        if (error.code === error.PERMISSION_DENIED) {
          stopLocationTracking();
        }
      },

      options
    );

    console.log('Started location tracking with watch ID:', watchId);
  } else {
    console.error('Geolocation not supported');
  }
}

function stopLocationTracking() {
  if (watchId !== null) {
    navigator.geolocation.clearWatch(watchId);
    watchId = null;
    console.log('Stopped location tracking');
  }
}

// Helper functions
let lastPosition = null;

function hasSignificantMovement(coords) {
  if (!lastPosition) {
    lastPosition = coords;
    return true;
  }

  const distance = calculateDistance(
    lastPosition.latitude, lastPosition.longitude,
    coords.latitude, coords.longitude
  );

  // Consider movement significant if > 10 meters
  if (distance > 10) {
    lastPosition = coords;
    return true;
  }

  return false;
}

function calculateDistance(lat1, lon1, lat2, lon2) {
  const R = 6371e3; // Earth's radius in meters
  const φ1 = lat1 * Math.PI/180;
  const φ2 = lat2 * Math.PI/180;
  const Δφ = (lat2-lat1) * Math.PI/180;
  const Δλ = (lon2-lon1) * Math.PI/180;

  const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) +
            Math.cos(φ1) * Math.cos(φ2) *
            Math.sin(Δλ/2) * Math.sin(Δλ/2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));

  return R * c; // Distance in meters
}

// Usage
startLocationTracking();

// Stop tracking after 5 minutes
setTimeout(stopLocationTracking, 5 * 60 * 1000);

