// Geolocation utility class
class LocationService {
  constructor() {
    this.watchId = null;
    this.lastKnownPosition = null;
  }

  // Check if geolocation is supported
  static isSupported() {
    return 'geolocation' in navigator;
  }

  // Get current position with promise interface
  async getCurrentPosition(options = {}) {
    return new Promise((resolve, reject) => {
      if (!LocationService.isSupported()) {
        reject(new Error('Geolocation is not supported'));
        return;
      }

      const defaultOptions = {
        enableHighAccuracy: true,
        timeout: 10000,
        maximumAge: 60000
      };

      navigator.geolocation.getCurrentPosition(
        (position) => {
          this.lastKnownPosition = position;
          resolve(position);
        },
        reject,
        { ...defaultOptions, ...options }
      );
    });
  }

  // Start watching position
  startWatching(callback, errorCallback, options = {}) {
    if (!LocationService.isSupported()) {
      if (errorCallback) errorCallback(new Error('Geolocation not supported'));
      return null;
    }

    const defaultOptions = {
      enableHighAccuracy: true,
      timeout: 5000,
      maximumAge: 0
    };

    this.watchId = navigator.geolocation.watchPosition(
      (position) => {
        this.lastKnownPosition = position;
        if (callback) callback(position);
      },
      errorCallback,
      { ...defaultOptions, ...options }
    );

    return this.watchId;
  }

  // Stop watching position
  stopWatching() {
    if (this.watchId !== null) {
      navigator.geolocation.clearWatch(this.watchId);
      this.watchId = null;
      return true;
    }
    return false;
  }

  // Get last known position
  getLastKnownPosition() {
    return this.lastKnownPosition;
  }

  // Calculate distance between two points
  static calculateDistance(pos1, pos2) {
    const R = 6371e3; // Earth's radius in meters
    const lat1 = pos1.coords ? pos1.coords.latitude : pos1.latitude;
    const lon1 = pos1.coords ? pos1.coords.longitude : pos1.longitude;
    const lat2 = pos2.coords ? pos2.coords.latitude : pos2.latitude;
    const lon2 = pos2.coords ? pos2.coords.longitude : pos2.longitude;

    const φ1 = lat1 * Math.PI/180;
    const φ2 = lat2 * Math.PI/180;
    const Δφ = (lat2-lat1) * Math.PI/180;
    const Δλ = (lon2-lon1) * Math.PI/180;

    const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) +
              Math.cos(φ1) * Math.cos(φ2) *
              Math.sin(Δλ/2) * Math.sin(Δλ/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));

    return R * c;
  }

  // Format coordinates for display
  static formatCoordinates(position, precision = 6) {
    const coords = position.coords || position;
    return {
      latitude: coords.latitude.toFixed(precision),
      longitude: coords.longitude.toFixed(precision),
      accuracy: coords.accuracy ? `±${Math.round(coords.accuracy)}m` : 'Unknown'
    };
  }
}

// Usage example
const locationService = new LocationService();

// Get current position
try {
  const position = await locationService.getCurrentPosition();
  const formatted = LocationService.formatCoordinates(position);
  console.log('Current location:', formatted);
} catch (error) {
  console.error('Failed to get location:', error.message);
}

// Watch for position changes
locationService.startWatching(
  (position) => {
    console.log('Position updated:', LocationService.formatCoordinates(position));
  },
  (error) => {
    console.error('Location error:', error.message);
  }
);
